          var isC = function(c){ return /^(code|code article|code article code|ref|reference)$/i.test(String(c).trim()); };
          var isL = function(c){ return /referencement|libelle|designation|produit|article$|intitule/i.test(norm(c).replace(/ /g, '')) || /^article$/i.test(String(c).trim()); };
          var hi = -1; rows.forEach(function(r, i){ if (hi < 0 && r.some(isC) && r.some(isL)) hi = i; });
          if (hi < 0) throw new Error('en-têtes code / produit introuvables');
