    try { if (typeof PRODUCTS_MDM !== 'undefined') lists.push(PRODUCTS_MDM); } catch(e){}
    try { if (typeof PRODUCTS_NATURALINE !== 'undefined') lists.push(PRODUCTS_NATURALINE); } catch(e){}
