    var l = lineBy(_scan.cur.k); if (!l) return sheetClose();
    var px = $('rl-sc-px').value; l.p = true; l.x = String(px).trim() === '' ? l.x : parsePrix(px); l.n = ($('rl-sc-nt').value || '').trim(); l.s = true;
    if (!l.e) l.e = _scan.cur.ean;
